from textbook_data import add


add("general", "01", "Общие положения", "Общие положения",
    "Термины, элементы дороги и базовые понятия, без которых невозможно правильно читать остальные главы.", [
("Зачем нужны точные термины",
 "Правила определяют порядок движения по дорогам Беларуси. Одно и то же действие может быть разрешено на проезжей части и запрещено на обочине или тротуаре, поэтому сначала необходимо определить, к какому элементу дороги относится место события. В вопросах экзамена формулировки «дорога», «проезжая часть» и «полоса движения» не взаимозаменяемы.",
 "Перед решением ситуации мысленно разделите пространство: проезжая часть предназначена для транспорта, тротуар — прежде всего для пешеходов, обочина примыкает к проезжей части, а разделительная полоса отделяет встречные направления. Не подменяйте юридический термин бытовым понятием «обочина у дороги» или «широкая полоса».",
 ["Дорога включает проезжую часть, тротуары, обочины и разделительные полосы при их наличии", "Перекрёсток не ограничивается только пятном пересечения асфальта", "Прилегающая территория не считается перекрёстком", "Пункты 1–2 главы 1 содержат термины, на которые ссылаются остальные нормы"]),
("Транспортное средство и водитель",
 "Механическое транспортное средство приводится в движение двигателем. К транспортным средствам относятся также велосипеды, гужевые повозки и другие предусмотренные Правилами средства передвижения. Водителем является человек, управляющий транспортным средством; к участникам движения относятся водители, пешеходы, пассажиры, велосипедисты, всадники и погонщики скота.",
 "Человек, ведущий велосипед или средство персональной мобильности рядом, выполняет требования для пешехода, а не продолжает считаться движущимся водителем. После посадки на велосипед или СПМ меняется правовой статус и набор разрешённых траекторий.",
 ["Наличие двигателя само по себе не разрешает движение везде", "Пешеход тоже является полноценным участником дорожного движения", "Обучающийся за рулём подпадает под правила для водителя с учётом специальных требований", "Точная категория определяет скорость, полосу и допустимые манёвры"]),
("Преимущество и требование уступить",
 "Преимущество означает право начать или продолжить движение раньше другого участника. «Уступить дорогу» требует не создавать помеху: участник, имеющий преимущество, не должен менять направление или скорость из-за ваших действий. «Предоставить преимущество» пешеходу требует дать ему возможность безопасно перейти проезжую часть.",
 "Преимущество не является разрешением проехать любой ценой. Если другой участник уже создал опасную ситуацию, следует остановиться и предотвратить ДТП, а не доказывать приоритет. После 1 сентября 2025 года особенно важно различать обязанность уступить транспорту и предоставить преимущество пешеходу.",
 ["Отсутствие необходимости тормозить у другого участника — главный практический критерий", "Знак приоритета не отменяет общей обязанности избегать опасности", "Пешеход на переходе оценивается по фактической траектории и расстоянию", "Пункт 2 разделяет понятия преимущества, уступить дорогу и предоставить преимущество"]),
("Видимость, обзорность и препятствие",
 "Видимость дороги — расстояние, на котором водитель способен распознать её элементы и участников. Ограниченная обзорность связана с геометрией дороги, растительностью, строениями и другими помехами обзору. Препятствием является неподвижный объект на полосе, который не позволяет продолжить движение по этой полосе.",
 "Стоящий в пробке автомобиль не превращается в «препятствие» только потому, что мешает проехать. Напротив, упавший груз или неисправный автомобиль могут быть препятствием. От этого различия зависят правила объезда, остановки и применение термина «обгон».",
 ["Снегопад и сумерки ухудшают видимость, но не отменяют требований ПДД", "Перед поворотом с плохой обзорностью нужно заранее уменьшить скорость", "Затор и препятствие — разные ситуации", "Объезд препятствия выполняется с учётом встречного и попутного транспорта"]),
("Населённый пункт и дорожная обстановка",
 "Границы населённого пункта определяются установленными знаками. Знаки с названием на белом фоне вводят специальные требования движения в населённом пункте, а знаки с иным оформлением могут обозначать только географическую границу без смены скоростного режима. Дорожная обстановка включает все факторы, которые водитель способен учитывать во время движения.",
 "Не ориентируйтесь на первые дома или табличку с названием без анализа её вида. После въезда проверьте знаки скорости и дополнительные таблички, а при выезде убедитесь, что зона действительно закончилась. В спорной ситуации выбирайте более осторожное поведение.",
 ["Белый фон знака населённого пункта меняет применяемый режим движения", "Конец застройки сам по себе не отменяет ограничений", "Дорожная обстановка требует постоянного, а не разового наблюдения", "Действующую редакцию терминов следует сверять с пунктом 2 Указа №551"]),
])


add("rights", "02", "Общие права и обязанности участников", "Права и обязанности",
    "Общие принципы безопасного поведения всех участников движения, ограничения и взаимодействие с представителями власти.", [
("Право пользоваться дорогой",
 "Участники дорожного движения вправе пользоваться дорогами в порядке, установленном Правилами и другими актами законодательства. Это право реализуется в пределах назначения конкретного элемента дороги и с учётом безопасности других людей. Никто не вправе самовольно изменять организацию движения, перекрывать проезд или создавать помехи.",
 "Право проезда не означает приоритет в каждой ситуации. Водитель обязан учитывать пешеходов, велосипедистов, состояние дороги и специальные режимы. Пешеход также не вправе использовать проезжую часть произвольно, если Правила предусматривают иной порядок.",
 ["Дорога используется по назначению её элементов", "Свой манёвр нужно согласовывать с безопасностью окружающих", "Самовольная установка знаков и ограждений недопустима", "Ограничения могут вводиться законом и техническими средствами организации движения"]),
("Безопасность и уважение других",
 "Участники обязаны соблюдать Правила, не создавать опасность и не наносить вред людям, транспорту, дорогам и имуществу. Следует быть внимательными и вежливыми, особенно по отношению к детям, пожилым людям, инвалидам и тем, кто испытывает затруднения при движении.",
 "Безопасное поведение начинается до формального нарушения: не нужно подрезать, блокировать переход, пугать пешехода звуковым сигналом или объезжать очередь по месту, предназначенному для встречного движения. Ошибка другого человека не освобождает от обязанности предотвратить последствия.",
 ["Опасное вождение недопустимо даже при наличии преимущества", "Уязвимым участникам требуется дополнительный запас времени и пространства", "Нельзя оставлять на дороге предметы, создающие угрозу", "Поведение оценивается по реальному риску, а не только по формальному праву проезда"]),
("Сохранение дороги и технических средств",
 "Запрещается повреждать дорожное покрытие, знаки, светофоры, ограждения и разметку, а также загрязнять дорогу способом, создающим опасность. Если повреждение или препятствие уже возникло, необходимо принять доступные меры предупредить других и сообщить ответственным службам.",
 "Вытекшее топливо, выпавший груз или сломанная ветка могут стать причиной тяжёлого ДТП. Не проезжайте мимо опасности без необходимой предосторожности, но и не останавливайтесь внезапно в месте, где ваш автомобиль создаст ещё больший риск.",
 ["Нельзя сжигать или оставлять опасные материалы на дороге", "Самовольно снимать и поворачивать дорожные знаки запрещено", "О повреждении светофора следует сообщить в дорожную или аварийную службу", "Предупреждение других не должно создавать новую опасность"]),
("Требования уполномоченных лиц",
 "Законные требования сотрудников милиции и других уполномоченных лиц, регулирующих движение в пределах своих полномочий, обязательны. Водитель должен остановиться при законном требовании, выполнить указания и не предпринимать действий, угрожающих безопасности людей.",
 "Сигнал сотрудника имеет приоритет перед обычным маршрутом водителя, но остановку следует выполнять контролируемо: снизить скорость, обозначить намерение и занять указанное место. При сомнении можно попросить представиться после остановки, не превращая дорогу в место спора.",
 ["Требование остановки выполняется без резкого манёвра", "Регулировщик действует в соответствии со своими полномочиями", "Документы предъявляются по законному требованию", "Несогласие не является основанием для скрытия или продолжения движения"]),
("Действия при возникшей опасности",
 "Если обстоятельства создают угрозу жизни, здоровью или имуществу, участник обязан по возможности содействовать её уменьшению. Особые обязанности возникают у водителя при ДТП, вынужденной остановке, приближении специального транспорта и в иных прямо предусмотренных случаях.",
 "Сначала обеспечьте собственную безопасность и обозначьте опасное место, затем помогайте в пределах своих возможностей. Неоправданные действия на проезжей части или перемещение пострадавшего без необходимости могут увеличить вред.",
 ["Не подвергайте себя опасности при попытке помочь", "Вызов экстренных служб уместен при угрозе людям", "Специальные главы 6 и 8 уточняют порядок действий", "Сохраняйте спокойствие и контролируйте обстановку вокруг"]),
])


add("duties", "03", "Права и обязанности водителей", "Обязанности водителя",
    "Документы, подготовка автомобиля, состояние водителя и поведение до, во время и после поездки.", [
("Документы и право управления",
 "Водитель механического транспортного средства обязан иметь документы, подтверждающие право управления и допуск транспортного средства к движению. При действующей электронной страховке порядок подтверждения страхования определяется законодательством. По законному требованию соответствующие документы предъявляются для проверки.",
 "Перед поездкой проверьте срок действия удостоверения, категорию и регистрационные данные автомобиля. Фотография документа не всегда заменяет предусмотренный законом оригинал или электронную форму. Не полагайтесь на привычку: требования к страховым документам менялись, поэтому сверяйтесь с действующей редакцией.",
 ["Категория должна соответствовать управляемому транспортному средству", "Регистрационный документ относится к конкретному автомобилю", "Электронный полис учитывается в установленном законом порядке", "Передача управления человеку без права управления недопустима"]),
("Проверка технического состояния",
 "До выезда водитель обязан убедиться в исправности и надлежащем состоянии транспортного средства. В пути необходимо контролировать показания приборов, появление посторонних звуков, запахов, изменение управляемости и торможения. При неисправности, создающей угрозу, движение следует прекратить в безопасном месте.",
 "Осмотр занимает немного времени: шины, световые приборы, номерные знаки, зеркала, стеклоочистители, отсутствие течей и закрепление груза. Сигнальная лампа не является украшением панели: при непонятной критической индикации безопаснее остановиться и выяснить причину.",
 ["Рабочее тормозное состояние проверяется до интенсивного движения", "Повреждённая шина или неработающий фонарь требует оценки допуска", "Номера должны быть читаемы и закреплены", "Перечень неисправностей находится в приложении 4"]),
("Ремни, посадка и контроль автомобиля",
 "Водитель обязан использовать предусмотренные конструкцией ремни безопасности и не начинать движение, пока не убедился в безопасности посадки пассажиров и размещения вещей. Положение за рулём должно позволять свободно управлять органами управления и наблюдать дорогу.",
 "Отрегулируйте сиденье и зеркала до трогания, а не на скорости. Телефон, навигатор и предметы на панели не должны закрывать обзор или отвлекать руки и внимание. Даже короткая поездка по двору требует пристёгивания, если ремни предусмотрены.",
 ["Пассажирская безопасность начинается до начала движения", "Управление одной рукой из-за телефона снижает контроль", "Не перевозите незакреплённые тяжёлые предметы в салоне", "Дети перевозятся с применением соответствующих удерживающих устройств"]),
("Состояния, при которых управление запрещено",
 "Нельзя управлять в состоянии опьянения, под воздействием веществ, ухудшающих реакцию, а также при болезненном состоянии или утомлении, если это ставит под угрозу безопасность. Запрещается передавать управление лицу, находящемуся в таком состоянии или не имеющему права управления.",
 "Лекарство, разрешённое к продаже, тоже может вызывать сонливость и замедлять реакцию. Прочитайте инструкцию, оцените самочувствие и при сомнении откажитесь от поездки. Кофе и открытое окно не восстанавливают утомлённому человеку полноценное внимание.",
 ["Алкогольное, наркотическое и иное опьянение несовместимо с управлением", "Утомление оценивается по реальной способности безопасно управлять", "Побочные действия лекарств необходимо учитывать", "Отдых является мерой безопасности, а не потерей времени"]),
("Поведение при неисправности и после поездки",
 "При возникновении опасной неисправности водитель должен принять меры к безопасной остановке, обозначению автомобиля и устранению угрозы. После остановки следует исключить самопроизвольное движение, безопасно открыть двери и не оставлять людей или животных в опасных условиях.",
 "На уклоне дополнительно используйте стояночный тормоз и безопасное положение колёс. Выходите со стороны, где нет движущегося транспорта. Оставленный в закрытом автомобиле ребёнок или животное может погибнуть даже при умеренной наружной температуре.",
 ["Стояночный тормоз применяется при стоянке", "Открывание двери требует предварительного наблюдения", "Ремонт на проезжей части выполняется только при крайней необходимости и с мерами защиты", "Правила вынужденной остановки связаны с главами 8 и 19"]),
])


add("pedestrian-duties", "04", "Права и обязанности пешеходов", "Пешеходы",
    "Безопасное движение по тротуару и проезжей части, переход дороги, видимость и поведение в особых условиях.", [
("Где должны двигаться пешеходы",
 "Пешеходы должны двигаться по тротуарам, пешеходным дорожкам и другим предназначенным для них элементам дороги. При их отсутствии или невозможности использования допускается движение в порядке, предусмотренном Правилами, с соблюдением безопасности и без создания помех транспорту.",
 "Не выходите на проезжую часть только потому, что тротуар занят припаркованным автомобилем: сначала оцените безопасный обход и видимость. Вне населённого пункта особенно важно выбирать предусмотренную сторону движения и сохранять максимальную заметность.",
 ["Тротуар и пешеходная дорожка имеют приоритет для пешего движения", "Велосипедная дорожка не является обычным местом прогулки", "Движение по обочине требует повышенного внимания к транспорту", "Пункт 17 главы 4 определяет порядок движения пешеходов"]),
("Переход проезжей части",
 "Переходить дорогу следует по пешеходному переходу, а при его отсутствии — в местах и порядке, разрешённых Правилами. Перед началом перехода необходимо оценить расстояние до транспорта, его скорость и траекторию, убедиться в безопасности и не создавать помех движению.",
 "Не начинайте переход из-за стоящего автомобиля, не видя соседних полос. Убедитесь не только в том, что водитель вас видит, но и в том, что он реально предоставляет преимущество. На широкой дороге оценивайте каждую следующую полосу отдельно.",
 ["Нерегулируемый переход требует взаимной видимости", "Нельзя полагаться только на зелёный сигнал без контроля поворачивающего транспорта", "Запрещено выбегать на дорогу", "Остановка на проезжей части допустима только при необходимости безопасности"]),
("Преимущество не отменяет осторожность",
 "На нерегулируемом пешеходном переходе пешеход имеет предусмотренное Правилами преимущество, однако обязан учитывать дорожную обстановку и не создавать аварийную ситуацию. Водитель обязан предоставить преимущество в установленных случаях, но пешеход должен убедиться, что переход безопасен.",
 "Право перехода не останавливает автомобиль физически. Тёмная одежда, наушники, зонт и телефон уменьшают способность заметить опасность. Сохраняйте зрительный контроль и не ускоряйтесь внезапно перед приближающимся транспортом.",
 ["Сначала безопасность, затем спор о преимуществе", "Поворачивающий автомобиль также обязан учитывать пешеходов", "Детей необходимо удерживать за руку и контролировать их траекторию", "Новая редакция уточняет предоставление преимущества по расстоянию и полосам"]),
("Тёмное время и недостаточная видимость",
 "При движении в тёмное время и при недостаточной видимости пешеходу следует использовать световозвращающие элементы, а в предусмотренных Правилами случаях их применение обязательно. На внешних световых приборах автомобиля пешеход становится заметен значительно позже, чем при наличии световозвращателей.",
 "Световозвращатель должен быть виден водителю со стороны приближающегося транспорта. Один небольшой элемент лучше разместить спереди и сзади либо на движущихся частях одежды. Фонарик телефона полезен, но не заменяет постоянную пассивную заметность при любых действиях.",
 ["Вне населённого пункта световозвращатели особенно важны", "Тёмная одежда сокращает время обнаружения пешехода", "Световозвращатели размещаются так, чтобы их не закрывали сумка или зонт", "Недостаточная видимость требует уменьшения скорости и от водителя"]),
("Запрещённые и опасные действия",
 "Пешеходам запрещается выходить на проезжую часть из-за препятствия без предварительной оценки обстановки, задерживаться на ней без необходимости и переходить в местах, где движение небезопасно или прямо запрещено. Отдельные ограничения действуют на автомагистралях, железнодорожных переездах и в зоне дорожных работ.",
 "Не обходите стоящий трамвай или автобус без видимости приближающегося транспорта. Дождитесь возможности безопасно обзореть дорогу в соответствии с правилами для остановочных пунктов. На автомагистрали пешеходу не место даже при поломке, кроме действий, непосредственно необходимых для безопасности.",
 ["Ограждение нельзя перелезать ради сокращения пути", "Игра и использование дороги как площадки недопустимы", "Остановочный транспорт закрывает обзор соседних полос", "Экстренная ситуация требует обозначения себя и безопасного отхода"]),
])


add("passenger-duties", "05", "Обязанности пассажиров", "Пассажиры",
    "Посадка и высадка, ремни безопасности, поведение в салоне и действия в аварийной ситуации.", [
("Безопасная посадка и высадка",
 "Посадка и высадка выполняются после полной остановки транспортного средства, со стороны тротуара или обочины, когда это возможно. Выход на проезжую часть требует предварительной проверки приближающегося транспорта. Пассажир не должен торопить водителя и побуждать его остановиться в запрещённом месте.",
 "Перед открытием двери посмотрите назад и убедитесь в отсутствии велосипедистов и автомобилей. Детей следует высаживать под контролем взрослого и уводить в безопасное место. После выхода не начинайте переход из-за автобуса, пока не восстановите обзор.",
 ["Дверь открывается только после остановки", "Высадка на проезжую часть требует особой осторожности", "Нельзя задерживать двери маршрутного транспорта", "Переход после высадки выполняется по правилам для пешеходов"]),
("Ремни и удерживающие устройства",
 "Пассажиры обязаны пристёгиваться предусмотренными конструкцией ремнями безопасности. Дети перевозятся с использованием удерживающих систем и по правилам, соответствующим возрасту, росту и конструкции транспортного средства. На мотоцикле используются застёгнутые мотошлемы в предусмотренных случаях.",
 "Ремень должен проходить правильно, без перекручивания и не по подушке. Один ремень не предназначен для двух человек. Детское кресло выбирается не только по возрасту, но и по инструкции производителя и совместимости с автомобилем.",
 ["Непристёгнутый пассажир опасен и для остальных людей в салоне", "Детское удерживающее устройство закрепляется по инструкции", "Ремень нельзя пропускать произвольным образом под мышкой", "Беременность не является причиной отказаться от правильно размещённого ремня"]),
("Поведение во время движения",
 "Пассажир не должен отвлекать водителя, мешать управлению, открывать двери или высовываться из транспортного средства во время движения. В маршрутном транспорте необходимо держаться за поручни, размещать вещи без блокирования проходов и соблюдать указания законных представителей перевозчика.",
 "Резкий возглас, спор или передача предмета водителю могут вызвать потерю контроля. Сообщите об опасности спокойно и только при реальной необходимости. Крупный багаж ставится так, чтобы при торможении он не переместился и не травмировал людей.",
 ["Стоящему пассажиру следует держаться за поручень", "Проходы и аварийные выходы нельзя загромождать", "Запрещается вмешиваться в работу органов управления", "Курение и иные запреты определяются законодательством и правилами перевозки"]),
("Перевозка в кузове и специальных местах",
 "Перевозка людей допускается только в местах и при условиях, предусмотренных Правилами и конструкцией транспортного средства. Нельзя перевозить пассажиров вне оборудованных мест, в непредназначенном прицепе или в положении, которое создаёт опасность при торможении и манёвре.",
 "Кузов грузового автомобиля не становится пассажирским салоном из-за наличия лавочки. Существуют специальные требования к оборудованию, водителю и организации такой перевозки. Для обычной поездки выбирайте оборудованное сиденье и исправный ремень.",
 ["Сиденье должно быть предусмотрено конструкцией", "Поездка на крыше, подножке или в багажнике недопустима", "Грузовой прицеп не предназначен для обычной перевозки людей", "Специальные перевозки выполняются по отдельным требованиям"]),
("Аварийная ситуация",
 "При ДТП или внезапной остановке пассажир должен сохранять спокойствие, выполнять законные указания водителя и спасателей, по возможности помогать детям и не выходить в опасную зону. При пожаре необходимо покинуть салон безопасным способом и отойти на безопасное расстояние.",
 "Если дверь заблокирована, используйте предусмотренный аварийный выход, не теряя время на сбор вещей. После эвакуации не возвращайтесь за багажом. Пострадавшему без необходимых навыков не изменяйте положение тела, если ему не угрожает непосредственная опасность.",
 ["Аварийные выходы обозначены в салоне", "При эвакуации вещи остаются в транспорте", "На дороге нужно отойти за ограждение или в иное безопасное место", "О происшествии сообщается в экстренные службы"]),
])


add("emergency", "06", "Водитель и другие лица в особых случаях", "Особые случаи",
    "ДТП, требования сотрудников, специальные транспортные средства и действия при непредвиденной опасности.", [
("Немедленные действия при ДТП",
 "Водитель, причастный к ДТП, обязан остановиться, включить аварийную световую сигнализацию и не перемещать связанные с происшествием предметы без установленной необходимости. Сначала нужно выяснить наличие пострадавших, обезопасить место и вызвать соответствующие экстренные службы.",
 "Не продолжайте движение «посмотреть повреждения позже». Включение аварийки не заменяет размещение знака аварийной остановки там, где он требуется. Фотографировать обстановку следует только после принятия мер безопасности и помощи пострадавшим.",
 ["Остановка и обозначение места — первые действия", "При пострадавших вызываются скорая помощь и милиция", "Следы и предметы сохраняются, если это не мешает спасению и безопасности", "Покидать место ДТП без законных оснований запрещено"]),
("Помощь пострадавшим",
 "При наличии пострадавших необходимо вызвать скорую помощь, а при невозможности вызова действовать в порядке, предусмотренном Правилами, чтобы обеспечить получение медицинской помощи. До приезда специалистов оказывается посильная первая помощь с учётом состояния пострадавшего.",
 "Сообщите точное место, число пострадавших, видимые признаки состояния и опасности вроде пожара. Не давайте лекарства и воду человеку без сознания. Перемещение оправдано при непосредственной угрозе жизни или невозможности иной помощи.",
 ["Диспетчеру передаются точные и краткие сведения", "При кровотечении применяются доступные методы его остановки", "Отсутствие сознания требует проверки дыхания и срочных действий", "Собственная безопасность остаётся обязательным условием помощи"]),
("Документирование и оформление",
 "Если пострадавших нет, водители действуют по установленному порядку фиксации обстоятельств и оформления ДТП, включая предусмотренные законом упрощённые процедуры при наличии условий. До перемещения транспорта важно зафиксировать положение, следы и взаимное расположение, когда это требуется.",
 "Не соглашайтесь на устную договорённость, если есть спор, скрытые повреждения или сомнения в документах. При допустимости европротокола или иной процедуры проверьте все законные условия, а не только отсутствие видимых травм.",
 ["Фотографии делаются с общих и детальных ракурсов", "Схема должна отражать реальные ориентиры и направление движения", "Данные участников и страховых документов проверяются", "Перемещение автомобилей не должно создавать затор и новую опасность"]),
("Остановка по требованию и проверка",
 "При законном требовании уполномоченного сотрудника водитель останавливается, соблюдая безопасность, и выполняет предусмотренные законом действия. Сотрудник может проверить документы, состояние транспортного средства и иные обстоятельства в пределах полномочий.",
 "Заблаговременно включите поворотник и остановитесь там, где это указано или где безопасно. Не выходите из автомобиля без необходимости, особенно на автомагистрали. Спор о правомерности не следует разрешать резким движением или попыткой уехать.",
 ["Остановка обозначается другим участникам", "Документы передаются по требованию без лишних действий", "Пассажирам также следует сохранять спокойствие", "После проверки в движение вливаются с учётом проезжающего транспорта"]),
("Приближение специального транспорта",
 "При приближении транспорта с включёнными специальными световыми и звуковыми сигналами водители обязаны предоставить преимущество в установленных Правилами случаях и не препятствовать проезду. Запрещается предпринимать манёвры, которые вынуждают такой транспорт резко тормозить или изменять траекторию.",
 "Оцените, откуда приближается автомобиль, заранее уменьшите скорость и освободите безопасный коридор. Не останавливайтесь внезапно на перекрёстке перед специальным транспортом. После его проезда убедитесь, что не следует второй автомобиль колонны.",
 ["Синие и красные проблесковые маячки применяются по своим правилам", "Преимущество предоставляется без резких и непредсказуемых действий", "Нельзя пристраиваться за специальным транспортом и повторять нарушения", "На перекрёстке учитываются сигналы и фактическая безопасность"]),
])


add("signals", "07", "Сигналы регулировщика и светофоров", "Светофоры",
    "Полный разбор основных и дополнительных сигналов, регулировщика, мигающих режимов и очерёдности.", [
("Приоритет регулировщика",
 "Сигналы регулировщика обязательны для водителей и пешеходов. Он вправе изменить обычную очерёдность, установленную светофорами и знаками приоритета. Положение корпуса и руки с жезлом или без него определяет, кому разрешено движение и из каких направлений требуется остановиться.",
 "Смотрите не только на жезл, но и на грудь, спину и бока регулировщика. Перед въездом убедитесь, что сигнал относится к вашему направлению. Не выезжайте по привычке на зелёный, если регулировщик запрещает движение.",
 ["Регулировщик имеет приоритет над светофором и знаками приоритета", "Сигнал рукой вверх требует внимания и выполнения последующего указания", "Вытянутые в стороны руки разрешают движение не всем направлениям", "Пункты 52–53 устанавливают точные значения положений регулировщика"]),
("Красный, жёлтый и зелёный",
 "Красный сигнал запрещает движение, жёлтый предупреждает о смене сигналов и в общем случае запрещает движение, зелёный разрешает движение с соблюдением других требований. Сочетание красного и жёлтого информирует о скором включении зелёного, но не разрешает начинать движение.",
 "Если остановка перед перекрёстком при жёлтом требует экстренного торможения, Правила предусматривают особый порядок продолжения движения. Не ускоряйтесь заранее на мигающий зелёный: лучше заранее спланировать плавную остановку.",
 ["Зелёный не отменяет обязанности уступить тем, кто завершает манёвр", "Красный с жёлтым не является разрешающим сигналом", "Жёлтый мигающий переводит перекрёсток в нерегулируемый режим", "Место остановки определяется стоп-линией, светофором и конфигурацией дороги"]),
("Дополнительные секции и стрелки",
 "Стрелка в дополнительной секции разрешает движение в указанном направлении, но её значение зависит от основного сигнала, включённого одновременно. При красном или жёлтом основном сигнале движение по дополнительной стрелке требует уступить транспорту с других направлений. При зелёном основном сигнале применяется иной приоритет.",
 "Не переносите правила обычного зелёного на зелёную стрелку при красном. Проверьте, ваша ли полоса связана с этой секцией знаками и разметкой. Если вы находитесь на крайней полосе и остановка заблокирует движение сзади, учитывайте специальное требование пункта 104.",
 ["Стрелка при красном разрешает только указанное направление", "По дополнительной секции при красном нужно уступить другим направлениям", "Знаки направления по полосам продолжают действовать", "Стрелки на основном сигнале имеют собственное значение для указанных траекторий"]),
("Сигналы для пешеходов и велосипедистов",
 "Пешеходные светофоры разрешают или запрещают переход по изображению соответствующей фигуры. Велосипедные светофоры адресованы велосипедистам и в предусмотренных случаях водителям СПМ. Мигающий разрешающий сигнал информирует о скорой смене, а не о гарантированном времени завершения манёвра.",
 "Пешеход не должен начинать переход на запрещающий сигнал, даже если машин временно нет. Велосипедист на проезжей части руководствуется применимым транспортным светофором, а на обозначенном велопереезде — специальными сигналами при их наличии.",
 ["Зелёная пешеходная фигура не отменяет контроль поворачивающего транспорта", "Красная фигура запрещает начинать переход", "Велосипедный силуэт относится к обозначенной зоне движения", "Мигающий сигнал требует трезвой оценки оставшегося времени"]),
("Трамвайные и неработающие светофоры",
 "Для трамваев могут применяться светофоры с бело-лунными сигналами, которые не адресованы остальным водителям. Если светофоры направления не работают либо их сигналы противоречивы, перекрёсток считается нерегулируемым при отсутствии регулировщика. Тогда действуют знаки приоритета и правила нерегулируемых перекрёстков.",
 "Не копируйте движение трамвая по бело-лунному сигналу. При отключении светофора снизьте скорость и заново определите главную и второстепенную дорогу. Если покрытие и приоритет определить невозможно, действуйте как на второстепенной дороге.",
 ["Бело-лунный сигнал предназначен прежде всего для трамвайного движения", "Мигающий жёлтый требует применения правил нерегулируемого перекрёстка", "Отключение светофора не означает автоматического преимущества главной дороги без знаков", "Приложение 1 содержит начертания и виды дорожных светофоров"]),
])
